<!--
 * Agent 审批（待审批列表页）
 *
 * @path apps/agent-web/src/views/approval/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * Agent 审批（待审批列表页）
 * <p>消费后端 HumanApprovalController 契约（auto-generated by bash/gen-contract.py）：
 * 数据源使用 listPending()（返回 Record<string, unknown>[]，列取值兼容），
 * 操作列「通过」「驳回」均打开审批处理弹窗（approval-form）。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';
import { Page, useYDSZModal } from '@ydsz/common-ui';
import { h } from 'vue';
import { ElButton } from 'element-plus';
import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { listPending } from '#/api/humanApproval';
import ApprovalForm from './approval-form.vue';

defineOptions({ name: 'ApprovalManagement' });

const gridOptions: VxeTableGridOptions<Record<string, unknown>> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'id', title: '审批ID', width: 200, showOverflow: true },
    { field: 'title', title: '标题', width: 180, showOverflow: true },
    { field: 'agentId', title: 'Agent ID', width: 150, showOverflow: true },
    { field: 'approver', title: '发起人', width: 120 },
    { field: 'status', title: '状态', width: 100 },
    { field: 'createTime', title: '创建时间', width: 170 },
    {
      field: 'action', title: '操作', width: 140, fixed: 'right',
      slots: { default: ({ row }) => h('div', { class: 'flex gap-1' }, [
        h(ElButton, { size: 'small', link: true, type: 'success', onClick: () => handleOpen(row, 'approve') }, () => '通过'),
        h(ElButton, { size: 'small', link: true, type: 'danger', onClick: () => handleOpen(row, 'reject') }, () => '驳回'),
      ]) },
    },
  ],
  height: 'auto',
  proxyConfig: {
    ajax: {
      query: async () => {
        const items = await listPending();
        return { items: items ?? [], total: items?.length ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};
const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });
const [ApprovalFormModal, approvalFormApi] = useYDSZModal({ connectedComponent: ApprovalForm });

/** 打开审批处理弹窗，action 标记默认操作（通过/驳回） */
function handleOpen(row: Record<string, unknown>, action: 'approve' | 'reject') {
  approvalFormApi.setData({ record: row, action });
  approvalFormApi.open();
}
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="待审批列表" />
    <ApprovalFormModal @success="gridApi.query()" />
  </Page>
</template>